package com.example.starter.observation;

import org.springframework.http.HttpStatus;

import java.util.List;

/**
 * 业务异常：携带 HTTP 状态及可选的冲突详情（冲突字段、当前版本），由全局异常处理器转为错误响应。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final List<String> conflictFields;
    private final Integer currentVersion;

    private ApiException(HttpStatus status, String message, List<String> conflictFields, Integer currentVersion) {
        super(message);
        this.status = status;
        this.conflictFields = conflictFields;
        this.currentVersion = currentVersion;
    }

    public HttpStatus status() {
        return status;
    }

    public List<String> conflictFields() {
        return conflictFields;
    }

    public Integer currentVersion() {
        return currentVersion;
    }

    /**
     * 400：请求参数不合法（如读数格式错误）。
     */
    public static ApiException badRequest(String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, message, null, null);
    }

    /**
     * 404：观测记录或基线版本不存在。
     */
    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, message, null, null);
    }

    /**
     * 409：通用冲突（记录已存在、删除版本不匹配、requestId 异参复用）。
     */
    public static ApiException conflict(String message, Integer currentVersion) {
        return new ApiException(HttpStatus.CONFLICT, message, null, currentVersion);
    }

    /**
     * 409：三方合并字段冲突，携带冲突字段与当前版本，不写入任何部分结果。
     */
    public static ApiException mergeConflict(List<String> conflictFields, int currentVersion) {
        return new ApiException(HttpStatus.CONFLICT,
                "merge conflict on fields: " + String.join(", ", conflictFields),
                List.copyOf(conflictFields), currentVersion);
    }

    /**
     * 410：记录已删除，拒绝新的修改和删除。
     */
    public static ApiException gone(String message) {
        return new ApiException(HttpStatus.GONE, message, null, null);
    }
}

package com.example.starter.observation;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.time.Instant;
import java.util.List;
import java.util.Map;

/**
 * 冲突解决响应：返回不可变解决记录要点及解决后指向版本的内容。
 *
 * @param resolutionId    全局唯一解决记录标识
 * @param observationId   观测记录唯一标识
 * @param requestId       生成该记录的请求标识
 * @param baseVersion     基线版本号
 * @param previousVersion 解决前当前版本号
 * @param version         解决后指向的版本号（无变化解决时等于 previousVersion）
 * @param contentChanged  解决后内容是否发生变化：false 表示未生成新观测版本
 * @param conflictFields  服务端重算出的冲突字段名列表
 * @param selections      各冲突字段的人工选择
 * @param operator        操作者标识
 * @param resolvedAtUtc   解决完成时刻（UTC，ISO-8601）
 * @param location        解决后版本的观测地点
 * @param reading         解决后版本的观测读数
 * @param note            解决后版本的观测备注
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record ResolutionResponse(
        String resolutionId,
        String observationId,
        String requestId,
        int baseVersion,
        int previousVersion,
        int version,
        boolean contentChanged,
        List<String> conflictFields,
        Map<String, String> selections,
        String operator,
        Instant resolvedAtUtc,
        String location,
        String reading,
        String note) {

    private static final TypeReference<Map<String, String>> SELECTIONS_TYPE = new TypeReference<>() {
    };

    /**
     * 由解决记录与指向版本的快照构造响应；选择映射从记录中的 JSON 原文反序列化。
     */
    public static ResolutionResponse of(ResolutionRecord record, ObservationSnapshot pointed,
                                        ObjectMapper objectMapper) {
        return new ResolutionResponse(
                record.resolutionId(),
                record.observationId(),
                record.requestId(),
                record.baseVersion(),
                record.previousVersion(),
                record.newVersion(),
                record.contentChanged(),
                List.copyOf(record.conflictFields()),
                parseSelections(record.fieldSelections(), objectMapper),
                record.operator(),
                record.resolvedAtUtc(),
                pointed.location(),
                pointed.reading(),
                pointed.note());
    }

    private static Map<String, String> parseSelections(String json, ObjectMapper objectMapper) {
        try {
            return objectMapper.readValue(json, SELECTIONS_TYPE);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to deserialize stored selections", e);
        }
    }
}

package com.example.starter.observation;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

import java.util.Map;

/**
 * 冲突解决请求：在普通三方合并收到冲突后，提交三个字段的完整候选值及对每个冲突字段的人工选择。
 *
 * @param requestId              全局唯一请求标识（幂等去重键）
 * @param resolutionId           全局唯一解决记录标识
 * @param baseVersion            离线修改所基于的基线版本号（服务端据此重新读取基线重算冲突）
 * @param expectedCurrentVersion 客户端预期的解决前当前版本号，不匹配返回 409
 * @param location               观测地点候选完整值
 * @param reading                观测读数候选完整值，十进制字符串，最多三位小数
 * @param note                   观测备注候选完整值
 * @param selections             冲突字段选择，键为字段名，值为 CURRENT 或 CANDIDATE；必须恰好覆盖本次仍冲突的字段
 * @param operator               操作者标识
 */
public record ResolveConflictRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String resolutionId,
        @NotNull @Min(1) Integer baseVersion,
        @NotNull @Min(1) Integer expectedCurrentVersion,
        @NotNull @Size(max = 512) String location,
        @NotNull @Pattern(regexp = "-?\\d+(\\.\\d{1,3})?", message = "reading must be a decimal string with at most 3 fraction digits")
        String reading,
        @NotNull @Size(max = 1024) String note,
        @NotNull Map<String, String> selections,
        @NotBlank @Size(max = 128) String operator) {
}

