15	/**
16	 * 冲突解决记录持久化：conflict_resolution 记录成功解决的完整上下文，不可变、永不更新。
17	 * 所有 SQL 使用参数化查询；冲突字段列表与选择映射以 JSON 原文存储。
18	 */
19	@Repository
20	public class ResolutionRepository {
21	
22	    private static final TypeReference<List<String>> FIELD_LIST_TYPE = new TypeReference<>() {
23	    };
24	    private static final TypeReference<java.util.Map<String, String>> SELECTIONS_TYPE = new TypeReference<>() {
25	    };
26	
27	    private final JdbcTemplate jdbcTemplate;
28	    private final ObjectMapper objectMapper;
29	
30	    public ResolutionRepository(JdbcTemplate jdbcTemplate, ObjectMapper objectMapper) {
31	        this.jdbcTemplate = jdbcTemplate;
32	        this.objectMapper = objectMapper;
33	    }
34	
35	    /**
36	     * 插入一条不可变解决记录；resolutionId 主键或 (observationId, requestId) 唯一键冲突时抛出重复键异常。
37	     */
38	    public void insert(ResolutionRecord record) {
39	        jdbcTemplate.update(
40	                "INSERT INTO conflict_resolution (resolution_id, observation_id, request_id, "
41	                        + "base_version, previous_version, new_version, candidate_location, candidate_reading, "
42	                        + "candidate_note, conflict_fields, field_selections, operator, content_changed, "
43	                        + "resolved_at_utc, created_at) "
44	                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
45	                record.resolutionId(),
46	                record.observationId(),
47	                record.requestId(),
48	                record.baseVersion(),
49	                record.previousVersion(),
50	                record.newVersion(),
51	                record.candidateLocation(),
52	                record.candidateReading(),
53	                record.candidateNote(),
54	                writeJson(record.conflictFields()),
55	                record.fieldSelections(),
56	                record.operator(),
57	                record.contentChanged(),
58	                Timestamp.from(record.resolvedAtUtc()));
59	    }
60	
61	    /**
62	     * 按全局唯一 resolutionId 查询解决记录；不存在时返回空。
63	     */
64	    public Optional<ResolutionRecord> findByResolutionId(String resolutionId) {
65	        return jdbcTemplate.query(
66	                        "SELECT resolution_id, observation_id, request_id, base_version, previous_version, "
67	                                + "new_version, candidate_location, candidate_reading, candidate_note, "
68	                                + "conflict_fields, field_selections, operator, content_changed, resolved_at_utc "
69	                                + "FROM conflict_resolution WHERE resolution_id = ?",
70	                        RESOLUTION_MAPPER, resolutionId)
71	                .stream().findFirst();
72	    }
73	
74	    /**
75	     * 按 observationId 按解决时刻先后查询全部解决记录。
76	     */
77	    public List<ResolutionRecord> findByObservationId(String observationId) {
78	        return jdbcTemplate.query(
79	                "SELECT resolution_id, observation_id, request_id, base_version, previous_version, "
80	                        + "new_version, candidate_location, candidate_reading, candidate_note, "
81	                        + "conflict_fields, field_selections, operator, content_changed, resolved_at_utc "
82	                        + "FROM conflict_resolution WHERE observation_id = ? "
83	                        + "ORDER BY resolved_at_utc ASC, resolution_id ASC",
84	                RESOLUTION_MAPPER, observationId);
85	    }
86	
87	    private String writeJson(Object value) {
88	        try {
89	            return objectMapper.writeValueAsString(value);
90	        } catch (JsonProcessingException e) {
91	            throw new IllegalStateException("failed to serialize resolution fields", e);
92	        }
93	    }
94	
95	    private List<String> readFieldList(String json) {
96	        try {
97	            return objectMapper.readValue(json, FIELD_LIST_TYPE);
98	        } catch (JsonProcessingException e) {
99	            throw new IllegalStateException("failed to deserialize conflict fields", e);
100	        }
101	    }
102	
103	    /**
104	     * 反序列化存储的选择 JSON；仅用于持久化层内部校验与比较，不参与记录不可变语义。
105	     */
106	    public java.util.Map<String, String> readSelections(String json) {
107	        try {
108	            return objectMapper.readValue(json, SELECTIONS_TYPE);
109	        } catch (JsonProcessingException e) {
110	            throw new IllegalStateException("failed to deserialize field selections", e);
111	        }
